INSERT INTO `knowledge_base` (`id`, `keyword`, `screen_name`, `feature_name`, `description`, `how_to_use`, `solution`, `screen_name_hi`, `feature_name_hi`, `description_hi`, `how_to_use_hi`, `solution_hi`, `screen_name_ta`, `feature_name_ta`, `description_ta`, `how_to_use_ta`, `solution_ta`) VALUES
  (201948, 'login', 'Login Screen', 'System Access', 'Login screen is used to enter username and password to access system.', 'Enter your assigned username and password to log in. Different roles (Admin, Operator) have different access levels.', 'Contact Admin if you forgot your credentials.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201949, 'trend', 'Trend Screen', 'Live/Historical Graph', 'Trend screen shows graphical data of machine values.', 'Navigate to Trend page from the sidebar to view live or historical data logs.', 'Use the filters to select specific date ranges or recipes.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201950, 'alarm', 'Alarm Screen', 'Alert Management', 'Alarm screen shows machine alarms. You can view active and historical alarms.', 'Open it from the sidebar menu to see alarm details and acknowledge them.', 'Resolve the physical issue on the machine and press Acknowledge.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201951, 'report', 'Report Screen', 'Data Export', 'The Report screen allows you to view and export production data as PDF.', 'Open Reports from the sidebar, select filters, and click Export or View.', 'Ensure a USB/printer is connected if exporting/printing.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201952, 'print', 'Report Screen', 'Print Data', 'To print report, open Report screen and click Print button.', 'Go to Reports, filter data, and select Print option.', 'Check printer connection and paper status.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201953, 'dashboard', 'Process Screen', 'Main Dashboard', 'The main dashboard shows live gauges, counters, and status.', 'Use the Process Screen button to see real-time machine telemetry.', 'Watch the gauges and counters for operational feedback.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201954, 'recipe', 'Recipe Page', 'Production Settings', 'Store and load machine parameters for different products.', 'Open Recipe page, select or create a recipe, and press Upload to PLC.', 'Ensure the machine is in a safe state before uploading.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201955, 'config', 'Settings', 'System Config', 'Configure system-wide settings and user permissions.', 'Access Settings from the sidebar (requires Admin/Manager role).', 'Only authorized personnel should change these settings.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201956, 'useradd', 'User Registration', 'New User', 'Add new operators or managers to the system.', 'Go to User Reg from the sidebar and fill in the details.', 'Ensure a unique username and strong password.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201957, 'io', 'IO Page', 'Digital Inputs/Outputs', 'Monitor the status of PLC binary inputs and outputs.', 'Go to Inputs or Outputs screen to see real-time signal status.', 'Green indicators mean the signal is ON, gray means OFF.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201958, 'reset', 'Process Screen', 'Reset Alarms', 'Allows resetting of active alarms or counters.', 'Use the Reset button on the dashboard or alarm page.', 'Ensure the fault condition is cleared before resetting.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201959, 'datalog', 'Data Log Page', 'Detailed Records', 'Contains detailed logs of every production cycle with timestamps.', 'Navigate to Data Log from the sidebar to view historical part data.', 'Use the export button to save logs as a spreadsheet.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201960, 'valve', 'Valve Sequence', 'Sequence Monitoring', 'Shows the active sequence of machine valves during a cycle.', 'Open Valve Sequence to monitor valve timings and states.', 'Useful for troubleshooting cycle irregularities.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201961, 'spec', 'Machine Specification', 'M/C Details', 'Contains technical specifications and dimensions of the machine.', 'View M/C Spec from the sidebar for maintenance or capacity checks.', 'Contact the manufacturer for any part replacements.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201962, 'manual', 'Manual Settings', 'Manual Control', 'Allows manual operation of the machine for setup purposes.', 'Navigate to Settings -> Manual Control to jog machine axes.', 'Ensure safety protocols are followed during manual movement.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201963, 'wo', 'Work Order', 'Production Tracking', 'Track production progress against specific orders.', 'Press \'Select W.O.\' on the dashboard to assign an order.', 'Actual count updates automatically as parts are produced.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201964, 'cp', 'SPC Stats', 'Process Capability (Cp)', 'Cp = (USL - LSL) / (6 * Sigma). It measures the potential capability of a process if it were perfectly centered.', 'View Cp on the Dashboard donut charts. It uses the last 30 days of data.', 'If Cp is low, investigate machine repeatability and variation.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201965, 'cpk', 'SPC Stats', 'Process Capability Index (Cpk)', 'Cpk = min((USL - Mean)/(3*SD), (Mean - LSL)/(3*SD)). It measures the actual process capability considering the mean centering.', 'Refreshed every 30 seconds on the Dashboard. High Cpk (>1.33) indicates a high-quality process.', 'If Cpk is much lower than Cp, the process mean is shifted. Adjust recipe parameters/offsets.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201966, 'ppk', 'SPC Stats', 'Performance Index (Ppk)', 'Ppk uses Total Variation (Population SD) instead of within-subgroup variation. It describes how the process actually performed.', 'Displayed on the Dashboard as a key quality metric.', 'Ideally Ppk should be close to Cpk for a stable process.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201967, 'oee', 'OEE Stats', 'Overall Equipment Effectiveness', 'OEE = Availability x Performance x Quality. It is a gold standard for measuring manufacturing productivity.', 'Tracked live on the Dashboard from PLC data.', 'Availability: Machine uptime. Performance: Actual vs Target speed. Quality: Good vs NG parts.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201968, 'oae', 'OAE Stats', 'Overall Asset Effectiveness', 'OAE = Availability x Performance x Quality. Similar to OEE, it measures how effectively assets are utilized.', 'View OAE/OEE donut chart on the main process screen.', 'Analyze downtime reasons to improve overall effectiveness.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201969, 'start', 'Process Screen', 'Cycle Start', 'Initiates the automatic hydraulic cycle based on the active recipe.', 'Press the Green START button in the header (if authorized).', 'Ensure all safety guards are closed before starting.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201970, 'stop', 'Process Screen', 'Cycle Stop', 'Stops the automatic cycle safely after the current stroke finishes.', 'Press the Red STOP button in the header.', 'For immediate stop, use the physical Emergency Stop mushroom button.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201971, 'download', 'Recipe Page', 'Write PLC', 'Sends the current recipe parameters from the HMI database to the PLC registers.', 'Press \'WRITE PLC\' on the Recipe page.', 'Wait for the \'Success\' confirmation before starting a cycle.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201972, 'upload', 'Recipe Page', 'Read PLC', 'Fetches the current live parameters from the PLC and updates the HMI screen.', 'Press \'READ PLC\' on the Recipe page.', 'Useful to see what settings the machine is currently using.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201973, 'save', 'Recipe Page', 'Save Recipe', 'Stores the on-screen parameters into the local HMI database.', 'Press \'SAVE\' or \'SAVE AS\' to store the product profile.', 'Give recipes descriptive names like \'REAR_FENDER_V2\'.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201974, 'export', 'Reports Page', 'Excel Export', 'Generates and saves a detailed report of production logs in .xlsx format.', 'Go to Reports, select Date/Work Order, and click \'EXPORT EXCEL\'.', 'Reports include timestamps, pressures, and operator names.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
  (201975, 'record', 'Trend Page', 'Start Recording', 'Begins logging live pressure and position data to the trend database.', 'Press \'START RECORDING\' on the Trend page.', 'Trends help analyze part quality over time.', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL);
