INSERT INTO `translations` (`id`, `context`, `msgid`, `en_US`, `ta_IN`, `si_LK`, `hi_IN`) VALUES
  (1, 'ChatManager', 'How can I help you today? You can ask about machine status, I/O, alarms, or features like \'recipe\' and \'reports\'.', 'How can I help you today? You can ask about machine status, I/O, alarms, or features like \'recipe\' and \'reports\'.', 'இன்று நான் உங்களுக்கு எப்படி உதவ முடியும்? நீங்கள் இயந்திரத்தின் நிலை, உள்ளீடு/வெளியீடு (I/O), எச்சரிக்கைகள் அல்லது \'ரெசிபி\' மற்றும் \'அறிக்கைகள்\' போன்ற அம்சங்களைப் பற்றிக் கேட்கலாம்.', 'අද මම ඔබට උදව් කරන්නේ කෙසේද? ඔබට යන්ත්‍ර තත්ත්වය, I/O, අනතුරු ඇඟවීම්, හෝ \'වට්ටෝරුව\' සහ \'වාර්තා\' වැනි විශේෂාංග ගැන විමසිය හැකිය.', NULL),
  (3, 'ChatManager', 'Hello! I am your HMI Assistant. How can I help you with the application today?', 'Hello! I am your HMI Assistant. How can I help you with the application today?', 'வணக்கம்! நான் உங்கள் HMI உதவியாளர். இன்று இந்தச் செயலியைப் பயன்படுத்த நான் உங்களுக்கு எப்படி உதவ முடியும்?', 'හෙලෝ! මම ඔබේ HMI සහකාර. අද අයදුම්පත සම්බන්ධයෙන් මට ඔබට උදව් කළ හැක්කේ කෙසේද?', NULL),
  (5, 'ChatManager', 'I\'m sorry, I couldn\'t find specific information about that. You can try asking about \'plc status\', \'active alarms\', or \'where is recipe page\'.', 'I\'m sorry, I couldn\'t find specific information about that. You can try asking about \'plc status\', \'active alarms\', or \'where is recipe page\'.', 'மன்னிக்கவும், அதுபற்றிய குறிப்பிட்ட தகவலை என்னால் கண்டுபிடிக்க முடியவில்லை. நீங்கள் \'பிஎல்சி நிலை\', \'செயலில் உள்ள எச்சரிக்கைகள்\' அல்லது \'செய்முறைப் பக்கம் எங்கே உள்ளது\' என்று கேட்டுப் பார்க்கலாம்.', 'කණගාටුයි, මට ඒ ගැන නිශ්චිත තොරතුරු සොයාගත නොහැකි විය. ඔබට \'plc තත්ත්වය\', \'ක්‍රියාකාරී අනතුරු ඇඟවීම්\' හෝ \'වට්ටෝරු පිටුව කොහේද\' ගැන විමසීමට උත්සාහ කළ හැකිය.', NULL),
  (7, 'MainWindow', 'BARANI HYDRAULICS INDIA PRIVATE LIMITED', 'BARANI HYDRAULICS INDIA PRIVATE LIMITED', 'பரானி ஹைட்ராலிக்ஸ் இந்தியா பிரைவேட் லிமிடெட்', 'බරානි හයිඩ්‍රොලික්ස් ඉන්දියා ප්‍රයිවට් ලිමිටඩ්', NULL),
